def table_title(n):
    return {'tb':'Tabla base · ','tbc':'Catálogo · ','tbd':'Detalle/asociación · ','w_':'Trazabilidad · '}.get(n[:3], 'Entidad · ')+n
def table_purpose(n):
    clues={'users':'usuarios y cuentas','products':'productos','categories':'categorías','buyer_orders':'órdenes de compra asignadas a vendedor','carts':'carritos','logs':'eventos de registro de operaciones','user_addresses':'direcciones asociadas a usuarios','payment_methods_types':'tipos de método de pago','address_components':'componentes estructurados de direcciones','carts_items':'renglones de carrito','order_items':'renglones de órdenes','products_categories':'asociación entre productos y categorías','products_users_providers':'asociación entre productos y proveedores/usuarios','user_payment_methods':'métodos de pago asociados a usuarios','users_wishlist_products':'asociación usuario-producto de lista de deseos'}
    s=n.split('_',1)[-1]
    return clues.get(s, 'información identificada por el nombre de la tabla; propósito pendiente de validación funcional')
def desc(c,t):
    n=c['name']; low=n.lower(); typ=c['type']
    refs=[]
    for fk in t['foreignKeys']:
      if n in fk['columns']:
       ix=fk['columns'].index(n); refs.append(f"FK hacia {fk['table']}.{fk['references'][ix]}")
    if c.get('generated'): tech='Columna generada por la expresión SQL '+c['generated']+'.'; fun='Su valor deriva de otras columnas; no se ingresa como valor independiente.'; certainty='Confirmado por el esquema'
    elif n in t['primaryKey']: tech='Identificador de fila declarado como clave primaria.'; fun='Identifica un registro de forma única dentro de esta tabla.'; certainty='Confirmado por el esquema'
    elif refs: tech='Columna participante en referencia declarada: '+', '.join(refs)+'.'; fun='Vincula este registro con la entidad referenciada; el significado comercial concreto requiere validación.'; certainty='Inferido por nombre y relación'
    elif low in ('creation_date','created_at','created_on'): tech='Marca temporal de creación almacenada.'; fun='Fecha/hora asociada a la creación del registro; no implica por sí sola historial.'; certainty='Inferido por nombre'
    elif low in ('last_update','updated_at','updated_on'): tech='Marca temporal de actualización; '+('se actualiza automáticamente al modificar la fila.' if c.get('onUpdate') else 'sin automatismo de actualización declarado.'); fun='Permite consultar una fecha de modificación registrada; no conserva versiones previas.'; certainty='Inferido por nombre'
    elif low in ('status','active','is_active','operation_status'): tech='Indicador de estado con tipo y restricciones definidos por el DDL.'; fun='Estado o habilitación del elemento; valores y semántica deben validarse salvo CHECK/ENUM.'; certainty='Inferido por nombre'
    elif low in ('id','sku','email','nickname','code'): tech='Atributo identificador o de referencia nominal'+(' y único.' if any(n in i['columns'] and i['kind']=='UNIQUE' for i in t['indexes']) else '.'); fun='Valor de identificación/código; interpretación exacta depende del dominio.'; certainty='Inferido por nombre'
    else: tech=f'Atributo almacenado con tipo SQL {typ}'+(' y nulabilidad opcional.' if c['nullable'] else ' y nulabilidad obligatoria.')
    if not (low in ('creation_date','created_at','created_on','last_update','updated_at','updated_on','status','active','is_active','operation_status','id','sku','email','nickname','code') or n in t['primaryKey'] or refs):
      fun='El nombre y el tipo acotan el dato almacenado; su significado funcional específico requiere validación.'; certainty='Pendiente de validación'
    if n in t['primaryKey']: certainty='Confirmado por el esquema'
    examples={'int':'42','bigint':'42','decimal':'123.45','varchar':'"texto"','char':'"ABC"','text':'"texto descriptivo"','datetime':'2026-10-20 12:00:00','date':'2026-10-20','timestamp':'2026-10-20 12:00:00','bit':"b'1'",'enum':"uno de los valores listados en el tipo",'tinyint':'1'}
    base=re.match(r'[a-z]+',typ.lower()); ex=examples.get(base.group(0) if base else '', 'valor compatible con '+typ)
    return {'technical':tech,'functional':fun,'certainty':certainty,'example':ex}

fks=[(t,f) for t in tables for f in t['foreignKeys']]
indexes=[(t,i) for t in tables for i in t['indexes']]
checks=[(t,c) for t in tables for c in t['checks']]
def unique_target(table_name, columns):
  target=byname.get(table_name)
  return bool(target and (set(target['primaryKey'])==set(columns) or any(i['kind']=='UNIQUE' and set(i['columns'])==set(columns) for i in target['indexes'])))
triggers=re.findall(r'TRIGGER\s+`([^`]+)`\s+(BEFORE|AFTER)\s+(INSERT|UPDATE|DELETE)\s+ON\s+`([^`]+)`',sql,re.I)
views=sorted(set(re.findall(r'CREATE\s+(?:ALGORITHM=.*?\s+)?VIEW\s+`([^`]+)`',sql,re.I)))
procs=sorted(set(re.findall(r'PROCEDURE\s+`([^`]+)`',sql,re.I)))
data_sections=set(re.findall(r'-- Dumping data for table `([^`]+)`',sql,re.I))
totalcols=sum(len(t['columns']) for t in tables)
for t in tables:
  t['functionalInterpretation']=table_purpose(t['name'])
  for c in t['columns']: c['documentation']=desc(c,t)
d.update({'source':'Practica03/backups/Respaldo_2010.sql','triggers':[{'name':n,'timing':ti.upper(),'event':ev.upper(),'table':tb} for n,ti,ev,tb in triggers], 'views':views,'procedures':procs,'checksTotal':len(checks),'indexesTotal':len(indexes),'tableCount':len(tables),'columnCount':totalcols})
(BASE/'schema.json').write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')

def md(s): return str(s).replace('|','\\|').replace('\n',' ')
lines=['# Diccionario de datos — `db_test`','',f"Fuente: `{d['source']}` · MySQL 8.0.36 · InnoDB · charset `utf8mb4` · collation `utf8mb4_0900_ai_ci`.",'','> Descripciones funcionales basadas en nombres y relaciones son inferencias pendientes de validación. Solo PK/FK/índices/DDL tienen confirmación directa. El respaldo contiene INSERT históricos; no se consultó una instancia activa.','', '## Cobertura','',f"- Tablas: {len(tables)} · Columnas: {totalcols} · PK: {sum(bool(t['primaryKey']) for t in tables)} · FK: {len(fks)} · UNIQUE: {sum(i['kind']=='UNIQUE' for _,i in indexes)} · índices (incluye PK/UNIQUE): {len(indexes)} · CHECK: {len(checks)}",f"- Triggers: {len(triggers)} · Vistas: {len(views)} · Procedimientos: {len(procs)}",'', '## Catálogo de tablas','']
for t in tables:
  lines += [f"### `{t['name']}`",'',f"**Título:** {table_title(t['name'])}  ",f"**Propósito técnico:** tabla física con {len(t['columns'])} columnas; motor {t.get('engine') or 'no explícito en parser'}.  ",f"**Propósito funcional:** representa probablemente {table_purpose(t['name'])} (interpretación basada en nombre; validar).  ",f"**PK:** {', '.join('`'+x+'`' for x in t['primaryKey']) or 'No declarada'}. **FK:** {len(t['foreignKeys'])}. **Dependencias:** {', '.join('`'+f['table']+'`' for f in t['foreignKeys']) or 'ninguna declarada'}.  ",f"**Trazabilidad/auditoría:** {'hay trigger(s) sobre esta tabla' if any(x['table']==t['name'] for x in d['triggers']) else 'sin trigger detectado para esta tabla'}.  ",f"**Filas INSERT en respaldo:** {t.get('rowCount') if t.get('rowCount') is not None else 'sin INSERT contabilizable'} (solo respaldo).",'', '|#|Columna|Tipo original|NULL|DEFAULT|PK/FK/UNIQUE/índices|Descripción técnica y funcional|Ejemplo ilustrativo|Certeza|','|---:|---|---|:---:|---|---|---|---|---|']
  for ix,c in enumerate(t['columns'],1):
    info=desc(c,t); keys=[]
    if c['name'] in t['primaryKey']: keys.append('PK')
    for fk in t['foreignKeys']:
     if c['name'] in fk['columns']: keys.append('FK → '+fk['table']+'.'+fk['references'][fk['columns'].index(c['name'])])
    for idx in t['indexes']:
     if c['name'] in idx['columns'] and idx['kind']=='UNIQUE': keys.append('UNIQUE '+idx['name'])
     elif c['name'] in idx['columns'] and idx['kind']=='INDEX': keys.append('IDX '+idx['name'])
    prop=[]
    if c.get('autoIncrement'): prop.append('AUTO_INCREMENT')
    if c.get('generated'): prop.append('GENERATED '+c['generated'])
    if c.get('onUpdate'): prop.append('ON UPDATE '+c['onUpdate'])
    if prop: keys+=prop
    lines.append(f"|{ix}|`{md(c['name'])}`|`{md(c['type'])}`|{'Sí' if c['nullable'] else 'No'}|{md(c.get('default') or '—')}|{md(', '.join(keys) or '—')}|{md(info['technical']+' '+info['functional'])}|`{md(info['example'])}`|{info['certainty']}|")
  lines += ['', '**Restricciones CHECK:** '+('; '.join('`'+md(x)+'`' for x in t['checks']) if t['checks'] else 'ninguna declarada.'),'','**Índices:** '+('; '.join(f"`{i['name']}` ({i['kind']}: {', '.join(i['columns'])})" for i in t['indexes']) or 'ninguno')+'.','']
lines+=['## Relaciones declaradas (FK)','', '|Origen|Columnas|Destino|Cardinalidad sustentada|ON DELETE|ON UPDATE|Nombre|','|---|---|---|---|---|---|---|']
for t,f in fks:
  card='muchos→uno' if unique_target(f['table'],f['references']) else 'muchos→muchos posibles (destino no único)'
  lines.append(f"|`{t['name']}`|`{', '.join(f['columns'])}`|`{f['table']}` (`{', '.join(f['references'])}`)|{card}|{f.get('onDelete') or 'no declarado'}|{f.get('onUpdate') or 'no declarado'}|`{f.get('name') or 'sin nombre'}`|")
lines+=['','Las relaciones se modelan por FK. La cardinalidad hacia destino es uno únicamente cuando las columnas destino coinciden con PK/UNIQUE; referencias a columnas no únicas permiten múltiples filas destino. `ON DELETE`/`ON UPDATE` solo aparecen cuando el DDL los declara. Las autorreferencias de `tbc_categories` y `tbd_address_components` están listadas; el ERD no dibuja el conector consigo misma.','', '## Tablas asociativas','', '- `tbd_products_categories`: asociativa confirmada por dos FK y PK compuesta; vincula producto y categoría. No agrega atributos no identificadores aparte de `status`, `creation_date` y `last_update`.', '- `tbd_products_users_providers`: asociativa confirmada por dos FK y PK compuesta; vincula producto con usuario/proveedor. `type_ownership`, estado y fechas son atributos propios.', '- `tbd_carts_items`: contiene FK a carrito y a IDs de producto/proveedor, con PK compuesta; su forma es asociativa, pero algunas FK destino no son únicas y existe una FK duplicada para `cart_ID`.', '- `tbd_users_wishlist_products`: su PK es compuesta, pero no declara FK; la hipótesis de asociación usuario-producto se basa solo en nombres y queda pendiente de validación.', '', '## Objetos programables y vistas','',f"- **Triggers:** {len(triggers)}; `AFTER INSERT/UPDATE/DELETE` detectados: "+(', '.join(f"`{n}` ({ti} {ev} en `{tb}`)" for n,ti,ev,tb in triggers) or 'ninguno')+'.',f"- **Vistas:** {len(views)}: "+(', '.join('`'+x+'`' for x in views) or 'ninguna')+'.',f"- **Procedimientos:** {len(procs)}: "+(', '.join('`'+x+'`' for x in procs) or 'ninguno')+'.','- **Funciones/eventos:** ninguno detectado mediante patrones de definición del respaldo.','', '## Auditoría y trazabilidad','', 'El esquema contiene `tb_logs` y triggers que escriben eventos (los 42 triggers son AFTER INSERT/UPDATE/DELETE). Parte de ellos intenta escribir en siete tablas `w_trazabilidad_*` que no aparecen entre las 15 tablas creadas; también hay triggers que escriben en `tb_logs`. Las vistas `vw_trazabilidad_*` derivan presentaciones de esos registros. Un timestamp de actualización no conserva versiones anteriores.','', '## Tipos de datos','', 'Tipos originales presentes: '+', '.join('`'+x+'`' for x in sorted({c['type'] for t in tables for c in t['columns']}))+'.','', '## Calidad y límites','', '- Cobertura: 15 tablas, 111 columnas; todas aparecen en el documento y CSV. No quedan tablas/columnas pendientes.', '- Restricciones extraídas: 15 PK, 17 FK declaradas (incluye duplicidad), 8 UNIQUE, 35 índices totales incluyendo PK y UNIQUE, 9 CHECK declarados (incluye duplicados).', '- Detectadas dos FK idénticas sobre `tbd_carts_items.cart_ID` (`fk_cart_items_cart` y `tbd_carts_items_ibfk_1`) y CHECK repetidos: `chk_cart_quantity`/`chk_cart_quantity_positive` validan la misma condición.', '- Siete destinos de trigger `w_trazabilidad_*` no tienen `CREATE TABLE` visible en el dump. Las vistas también consultan `mysql.role_edges`, objeto externo al esquema `db_test`.', '- Los conteos INSERT son únicamente del contenido del respaldo y no representan una instancia actual. Descripciones funcionales siguen siendo interpretaciones basadas en nombres y contexto estructural.', '- No se ejecutó SQL ni se restauró ni modificó el esquema.','']
(BASE/'diccionario.md').write_text('\n'.join(lines),encoding='utf-8')

with (BASE/'columnas.csv').open('w',newline='',encoding='utf-8-sig') as f:
  w=csv.DictWriter(f,fieldnames=['tabla','orden','columna','tipo_original','longitud_precision_escala','nullable','default','pk','fk','referencia','unique','indices','auto_increment','generated','on_update','check','descripcion_tecnica','descripcion_funcional','ejemplo_ilustrativo','certeza']); w.writeheader()
  for t in tables:
   for ix,c in enumerate(t['columns'],1):
    info=desc(c,t); fks_here=[fk for fk in t['foreignKeys'] if c['name'] in fk['columns']]; indexes_here=[i for i in t['indexes'] if c['name'] in i['columns']]
    w.writerow({'tabla':t['name'],'orden':ix,'columna':c['name'],'tipo_original':c['type'],'longitud_precision_escala':re.search(r'\([^)]*\)',c['type']).group(0)[1:-1] if re.search(r'\([^)]*\)',c['type']) else '', 'nullable':'sí' if c['nullable'] else 'no','default':c.get('default') or '', 'pk':'sí' if c['name'] in t['primaryKey'] else 'no','fk':'sí' if fks_here else 'no','referencia':'; '.join(f"{fk['table']}.{fk['references'][fk['columns'].index(c['name'])]}" for fk in fks_here),'unique':'; '.join(i['name'] for i in indexes_here if i['kind']=='UNIQUE'),'indices':'; '.join(i['name'] for i in indexes_here if i['kind']=='INDEX'),'auto_increment':c.get('autoIncrement'),'generated':c.get('generated') or '', 'on_update':c.get('onUpdate') or '', 'check':'; '.join(t['checks']),'descripcion_tecnica':info['technical'],'descripcion_funcional':info['functional'],'ejemplo_ilustrativo':info['example'],'certeza':info['certainty']})

# Native Archify ERD: every physical column included. Self-relations stay documented in Markdown/HTML.
entities=[]; rels=[]
for i,t in enumerate(tables):
  attrs=[]
  for c in t['columns']:
    roles=[]
    if c['name'] in t['primaryKey']: roles.append('pk')
    for fk in t['foreignKeys']:
      if c['name'] in fk['columns']: roles.append('fk')
    if any(c['name'] in ix['columns'] and ix['kind']=='UNIQUE' for ix in t['indexes']): roles.append('uk')
    a={'name':c['name'],'type':c['type']}
    if roles:a['key']=roles[0] if len(roles)==1 else roles
    if 'fk' in roles:
      fk=next(f for f in t['foreignKeys'] if c['name'] in f['columns']); a['references']=f"{fk['table']}.{fk['references'][fk['columns'].index(c['name'])]}"
    attrs.append(a)
  widest=max((len(c['name'])*7+len(c['type'])*6+105 for c in t['columns']),default=280)
  entities.append({'id':t['name'],'label':t['name'],'row':i//2,'col':i%2,'width':min(820,max(300,widest)),'attributes':attrs})
for t,f in fks:
  if t['name']==f['table']: continue
  uniq=any(ix['kind']=='UNIQUE' and ix['columns']==f['columns'] for ix in t['indexes'])
  optional=any(next(c for c in t['columns'] if c['name']==x)['nullable'] for x in f['columns'])
  rels.append({'id':(f.get('name') or t['name']+'_'+str(len(rels)+1)).replace(' ','_'),'from':t['name'],'to':f['table'],'label':', '.join(f['columns'])+' → '+', '.join(f['references']),'fromCardinality':'one' if uniq else 'many','toCardinality':'one' if unique_target(f['table'],f['references']) else 'many','fromOptional':optional})
candidate={'schema_version':1,'diagram_type':'erd','meta':{'title':'Modelo relacional · db_test','locale':'es','subtitle':'MySQL 8.0.36 · 15 tablas · columnas físicas y FK declaradas','output':str(BASE/'modelo-relacional.html').replace('\\','/'),'quality_profile':'standard'},'layout':{'mode':'grid','gapY':40,'gapX':70},'entities':entities,'relationships':rels,'cards':[{'dot':'cyan','title':'Lectura del modelo','items':['Fuente: respaldo_2010.sql. Todos los campos físicos están incluidos.','Solo se muestran conectores soportados por FOREIGN KEY.','Las autorreferencias se documentan en el diccionario porque el ERD no admite conectar una entidad consigo misma.','El esquema lista 15 tablas y 17 claves foráneas.']} ]}
